package com.simon.voiceime;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
/** Literal geometry and WCAG formula come from the approved specification. */
public class App689VisualTest {
 private Object v(String method,Class<?>[] types,Object... args)throws Exception {Class<?> c;try{c=Class.forName("com.simon.voiceime.DualHandVisuals");}catch(ClassNotFoundException absent){throw new AssertionError("6.89 visual implementation absent",absent);}return c.getMethod(method,types).invoke(null,args);}
 private int color(boolean dark,String role)throws Exception{return (Integer)v("color",new Class[]{boolean.class,String.class},dark,role);}
 private double linear(double x){x/=255;return x<=.04045?x/12.92:Math.pow((x+.055)/1.055,2.4);}
 private double lum(int c){return .2126*linear(c>>16&255)+.7152*linear(c>>8&255)+.0722*linear(c&255);}
 @Test public void c_zonePaletteAndContrast()throws Exception{assertEquals(0xFF161B26,color(true,"left"));assertEquals(0xFF1C2230,color(true,"right"));assertEquals(0xFF1E293B,color(true,"zero"));assertEquals(0xFF252D3D,color(true,"core"));assertEquals(0xFFF8F9FA,color(false,"tools"));for(boolean dark:new boolean[]{false,true})for(String role:new String[]{"left","right","zero","core","tools"})for(String text:new String[]{"secondary","hint"}){double a=lum(color(dark,role)),b=lum(color(dark,text));assertTrue(role+text,(Math.max(a,b)+.05)/(Math.min(a,b)+.05)>=4.5);}}
 @Test public void a45_portraitAndLandscapeGeometry()throws Exception{assertEquals(.4f,(Float)v("leftFraction",new Class[]{float.class},400f),.01);assertTrue((Float)v("leftFraction",new Class[]{float.class},320f)*314/2-4>=64);assertEquals(50f,(Float)v("landscapeRowDp",new Class[]{float.class},360f),0);assertEquals(182f,32+3*(Float)v("landscapeRowDp",new Class[]{float.class},360f),0);assertEquals(-1f,(Float)v("landscapeRowDp",new Class[]{float.class},200f),0);}
 @Test public void e_k_emptyCenterDotAndNonemptySwipeHighlight()throws Exception{for(String value:new String[]{"","ㄧ","ㄨㄚ"}){assertEquals(value.isEmpty(),v("guideDot",new Class[]{String.class},value));assertEquals(!value.isEmpty(),v("highlight",new Class[]{String.class,String.class},"up",value));assertEquals(false,v("highlight",new Class[]{String.class,String.class},"tap",value));}}
 @Test public void g_capsuleAndBubbleStayVisible()throws Exception{int[] upper=(int[])v("capsulePosition",new Class[]{int.class,int.class,int.class,int.class,int.class},4,10,30,400,300);assertArrayEquals(new int[]{0,26},upper);int[] lower=(int[])v("capsulePosition",new Class[]{int.class,int.class,int.class,int.class,int.class},396,280,296,400,300);assertArrayEquals(new int[]{368,260},lower);assertEquals(0,(int)v("clamp",new Class[]{int.class,int.class,int.class},-10,60,400));assertEquals(340,(int)v("clamp",new Class[]{int.class,int.class,int.class},399,60,400));}
}
